export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            clearTimeout(timer);
            timer = null;
            return;
        }
        timer = setTimeout(() => {
            clearTimeout(timer);
            timer = null;
            fn(...args);
        }, waitMs);
    };
}
```

